// Types for the modules generated by vite-plugin-content.ts.
declare module 'virtual:content' {
  import type { Scenario, Track } from './schema/scenario.ts'
  import type { Challenge } from './schema/challenge.ts'
  import type { CanvasChallenge } from './schema/canvas.ts'
  import type { Provider } from './schema/multi.ts'
  import type { QueueItem } from './screens/HomeScreen.tsx'

  type MultiBase = {
    id: string
    track: string
    title: string
    difficulty: number
    providers: Provider[]
    differences: Record<string, string>
  }
  export type MultiChallenge =
    | (MultiBase & { kind: 'canvas'; variants: Partial<Record<Provider, CanvasChallenge>> })
    | (MultiBase & { kind: 'slot'; variants: Partial<Record<Provider, Challenge>> })

  // One playable item's full content, loaded on demand as its own chunk.
  export type Item =
    | { kind: 'incident'; scenario: Scenario }
    | { kind: 'challenge'; challenge: Challenge }
    | { kind: 'canvas'; canvas: CanvasChallenge }
    | { kind: 'multi'; multi: MultiChallenge }

  // The index: everything the queue, skill tree and unlocks need.
  const content: { tracks: Track[]; items: QueueItem[] }
  export default content
  export function loadItem(id: string): Promise<Item>
}
